// Demo workflow: rolls up the previous day into one summary item.
// Zero credentials and no outbound calls — the numbers are derived from the
// clock, not from a real source. It exists so a fresh install shows a second
// schedule cadence next to the 30-minute one on the architecture map.
const now = new Date();
const since = new Date(now.getTime() - 24 * 60 * 60 * 1000);
return [
  {
    json: {
      window_start: since.toISOString(),
      window_end: now.toISOString(),
      title: `Digest for ${since.toISOString().slice(0, 10)}`,
      status: 'info',
    },
  },
];
